using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class Sports742Verify{const string D="Assets/Scenes/Oasis/StreetSports742/",R="FinalEnvironmentRoadReview/Sports742";static Sports742Verify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("Sports742Verify.request"))return;File.Delete("Sports742Verify.request");try{Run();}catch(Exception e){File.WriteAllText(R+"Verified.txt",e.ToString());Debug.LogException(e);}}
