var ballPaths=balls.Select(c=>PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(c.gameObject)).Distinct().ToArray();bool centered=balls.All(c=>c.center.sqrMagnitude<.000001f&&c.GetComponentsInChildren<MeshFilter>(true).All(f=>f.transform.localPosition.sqrMagnitude<.000001f&&f.sharedMesh.bounds.center.sqrMagnitude<.000001f));bool shared=balls.All(c=>PrefabUtility.IsPartOfPrefabInstance(c));if(!centered||!shared||ballPaths.Length!=2)throw new Exception("Ball prefab centering / sharing check failed");
File.WriteAllText(R+"QualityVerified.txt","SUCCESS football/basketball source prefabs="+ballPaths.Length+" shared instances="+balls.Length+" centred mesh/transform/collider pivots="+centered+" linked prefabs="+shared+". Football has 12 black pentagons and 20 white hexagons with curved panels and recessed seams; basketball has smoother round geometry, procedural dark panel seams and existing-atlas leather detail. Both use existing material, near/far LODs and spherical colliders. Ball racks, reused bins, zone labels, walkway joints, court marks, improved hoop/net added. No new material / texture assets. Native plot unchanged.\n"+string.Join("\n",ballPaths));
var mats=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().ToArray();var newM=AssetDatabase.FindAssets("t:Material",new[]{"Assets"}).Except(File.ReadAllLines(R+"BeforeMaterialGUIDs.txt")).ToArray();var newT=AssetDatabase.FindAssets("t:Texture2D",new[]{"Assets"}).Except(File.ReadAllLines(R+"BeforeTextureGUIDs.txt")).ToArray();if(newM.Length!=0||newT.Length!=0||mats.Any(m=>ShaderUtil.ShaderHasError(m.shader)))throw new Exception("Material/texture/shader validation failed");
File.WriteAllText(R+"Verified.txt","SUCCESS saved sports hub prefab / scene. New material assets="+newM.Length+" new Texture2D assets="+newT.Length+" new Lights="+root.GetComponentsInChildren<Light>(true).Length+" bench instances="+root.GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("Existing bench reused"))+" cone instances="+root.GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("Existing traffic cone reused")||t.name.StartsWith("Existing training cone reused"))+" shared existing materials="+mats.Length+" total near triangles including reused props="+root.GetComponentsInChildren<MeshFilter>(true).Sum(f=>f.sharedMesh.triangles.Length/3)+" shader errors=False. LOD detail culling, two fence entrance gaps, original polySurface742 geometry and material unchanged. Four actual Unity views captured.");EditorSceneManager.SaveScene(scene);}
